create extension if not exists pgcrypto;
create type case_type as enum ('aid','orphan_sponsorship');
create type child_gender as enum ('male','female');
create type case_status as enum ('active','waiting','inactive');
create type app_role as enum ('admin','reviewer');
create table public.cases(id uuid primary key default gen_random_uuid(),mother_name text not null,phone text not null,address text not null,case_type case_type not null,notes text,status case_status not null default 'active',priority_override integer,priority_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.children(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases(id) on delete cascade,name text not null,gender child_gender not null,birth_date date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.amount_rules(id uuid primary key default gen_random_uuid(),name text not null,case_type case_type not null,child_count integer,amount numeric(12,2) not null check(amount>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,user_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,details jsonb,created_at timestamptz not null default now());
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,full_name text,role app_role not null default 'reviewer',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.current_role() returns app_role language sql stable security definer set search_path=public as $$ select coalesce((select role from public.profiles where user_id=auth.uid()),'reviewer'::app_role) $$;
alter table public.cases enable row level security;alter table public.children enable row level security;alter table public.amount_rules enable row level security;alter table public.audit_logs enable row level security;alter table public.profiles enable row level security;
create policy "authenticated users can read cases" on public.cases for select to authenticated using(true);create policy "authenticated users can insert cases" on public.cases for insert to authenticated with check(true);create policy "authenticated users can update cases" on public.cases for update to authenticated using(true) with check(true);create policy "authenticated users can delete cases" on public.cases for delete to authenticated using(public.current_role()='admin');
create policy "authenticated users can read children" on public.children for select to authenticated using(true);create policy "authenticated users can insert children" on public.children for insert to authenticated with check(true);create policy "authenticated users can update children" on public.children for update to authenticated using(true) with check(true);create policy "authenticated users can delete children" on public.children for delete to authenticated using(public.current_role()='admin');
create policy "authenticated users can read amount rules" on public.amount_rules for select to authenticated using(true);create policy "admins can manage amount rules" on public.amount_rules for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');
create policy "authenticated users can read audit logs" on public.audit_logs for select to authenticated using(true);create policy "authenticated users can insert audit logs" on public.audit_logs for insert to authenticated with check(user_id=auth.uid());
create policy "users can read own profile" on public.profiles for select to authenticated using(user_id=auth.uid());create policy "admins can manage profiles" on public.profiles for all to authenticated using(public.current_role()='admin') with check(public.current_role()='admin');
alter publication supabase_realtime add table public.cases;alter publication supabase_realtime add table public.children;alter publication supabase_realtime add table public.amount_rules;alter publication supabase_realtime add table public.profiles;
create or replace function public.is_child_eligible(p_gender child_gender,p_birth_date date) returns boolean language sql immutable as $$ select case when p_gender='female' then true else age(current_date,p_birth_date)<interval '18 years' end $$;
create or replace function public.case_eligible_children(p_case_id uuid) returns bigint language sql stable as $$ select count(*) from public.children where case_id=p_case_id and public.is_child_eligible(gender,birth_date) $$;
